cards.append(compact('zhuosikawa','卓丝卡娃','卓丝卡娃是苏联科学院的高级院士，长期从事科学研究，在通古斯事件的解释上主张过外星飞船的可能，既有大胆假说，也能面对同行异议。齐白把一块合金交来时，她最初觉得研究普通物件不合身份，真正测试后却完全改变看法：仪器读数不断达到上限，现有设备不足以量出磁能，因此她急切寻找已经把物件带走的齐白。她不善于人际应对，初见卫斯理时试图贬低合金价值，旋即露出破绽，最后坦率说明研究和风险。她谈到的世界毁灭是理论最坏可能，依赖尚未找到的释放装置，不能算她已经拥有毁灭地球的武器，更不能把仪器测不出上限写成真正无限能量。故事最终说明合金只用来完成一次远程立体通讯，能量随后耗尽；她再次来电时没有获知完整真相。卡片保留专业尊严、研究执著与对误用技术的忧虑，不把院士头衔变成万能解题权限。遇到新物件时，她会先测量、检查仪器能力，再讨论机制；被人藏起信息时会坚持追问，也可能在学术自尊和合作效率之间犯不必要的错。','《异宝》仍试图追问研究结果，但未得到完整通讯真相；合金实际能量已消失','主角','弄清异常材料并防止不明装置被误用','严肃讲理，谈专业时清晰，社交中有时以身份维护自尊','证据超出仪器时承认未知并积极追查，失去样本会愤懑','读数封顶只说明测量边界，风险推演不等于已经拥有对应火力',[ab('磁学与异常材料研究','用多种测试判断合金强磁性质，区分材料与能量释放装置','设备有上限，具体机制未知；没有制造或使用毁星武器的能力'),ab('跨领域科学假说','研究通古斯事件并提出可讨论解释','假说仍需证据，不能把外星起源视为所有异常的自动答案')],[ev('066',551,655,'身份及研究背景'),ev('066',662,715,'测量上限和风险条件'),ev('066',721,750,'失去样本和求助目的'),ev('066',2941,2961,'通讯结束及她仍追问')],profile='expert',aliases=['卓丝卡娃院士']))
cards.append(compact('tomb_giant','建陵外星巨人','建陵外星巨人是曾到地球的星际旅者之一，因把万里长城误认作文明的降落指示，与同伴停留观察，并接触秦王。他把领袖理解为智慧的代表，却发现皇帝要求长生和所有人服从意志，不能理解这种权力欲，最后只答应协助建造安置尸体的宏伟陵墓。两千多年后，卫斯理、齐白和陈长青偶然启动遗留装置，他从仍在航行的远处以立体影像现身，愿调小投影方便谈话，也认真解释中枢和脑能的关系。他对人类自相残杀、屈服与奴役的评论并无明显恶意，却带着文明差距造成的直率，令听者难堪；他自己也曾误判人类会在漫长时间后自然改进。此次联系履行的是只见一次的旧约，接收能量耗尽后中断，合金变成普通钥匙扣，不能供地球朋友随时召唤。卡片保留其文明知识、有限技术支持与愿意交流的态度，不把投影不可触摸等同本体无敌，也不把团队工程或母文明全部力量变成本人随身攻击。新的接触应具体说明通信与航行条件，他仍可能被地球人的锁、钥匙和私有防范困惑，而不是从第一句就全知所有文化。','《异宝》仍在星际航道上，完成一次限定通讯；地球接收装置能量耗尽，不能随时再次联系','主角','探索星际生命并履行有限承诺，拒绝替地球皇帝实现统治欲','温和直接，愿用可理解的比较讲技术，也会真诚困惑于人类习惯','被要求长生或强制服从时拒绝，交流时间有限便催促问题','技术支持可以有边界，文明先进也不保证理解他者所有动机',[ab('星际立体通讯','利用航行端与陵墓接收装置远程现像，调节投影比例并交流','投影不能触碰；地球一侧一次能源已耗尽，非本体瞬移或无限召唤'),ab('脑能与工程知识','了解脑能、磁能及陵墓中枢，曾与同伴建造系统','需装置和团队条件；没展示个人将强磁能当武器或随身造完整陵墓')],[ev('066',2800,2849,'来历、团队和投影'),ev('066',2865,2918,'对人类判断与建陵'),ev('066',2922,2958,'通讯位置、一次限制与终止')],profile='expert'))
