cards.append(compact('liu_ju','刘巨','刘巨是享有声誉的人像雕塑大师，姓名十分中国化，血统在叙述中没有完全确定。他善于从姿态、细节和材料判断雕像，两个有天分学生引他去米端的蜡像院，所见却强烈动摇了他对自身艺术的理解。他先把米端当作市侩，愤怒要求见真正作者，再以触摸、小刀和血迹检验，得出那些并非蜡像而是真人的怀疑。这个结论遭到常识反驳，他仍寻求卫斯理、白素和白奇伟协助，并在展馆起火时冲入，外人一度以为他已被烧死。终局米端说明曾把他转离火场，为惩戒其无礼而送进一处小沙漠，需吃几天苦才能出来；文本没有进一步展示他返回后的反应。卡片须以生还而暂困的状态处理，不能误记成死亡复活，也不能因为识破真像便获得读心或灵魂视觉。他的专业敏感是优势，受挫的自尊使他粗鲁与冒险则是另一面。新的场景中，他可以从材质和动作提出精确问题，也应有机会承认自己的判断正确并不意味着质问方式不会伤害关系。','《极刑》由米端救离火场并被放在沙漠惩戒，仍活着，返回时间未详述','主角','弄清超出自己艺术经验的展品，维护技艺与判断的尊严','善察人体姿态和材质，重视真正作者和艺术价值','专业自信受震动时愤怒追索，可能不顾安全冲入现场','发现矛盾应靠实物核验，身份和声望不能成为羞辱他人的理由',[ab('人像雕塑与材质判断','凭长期经验发现陈列人体异样，触摸、划痕和血迹支持真人判断','并非天生通灵；需接触和材料，陌生生命机制仍不知道'),ab('追查与求助','主动求见调查者、讲清自身观察并参与现场检查','缺少潜入和火场救援训练，勇敢不保证安全')],[ev('067',731,819,'身份、受震动和无礼冲突'),ev('067',923,968,'求助及实际检测'),ev('067',3249,3252,'被救及沙漠终局')],profile='expert'))
cards.append(compact('li_ya','李亚','李亚是白奇伟南美工程队的助手，熟悉当地环境和关于瀑布、山洞的传说，因而在异常出现时比来自外地的工程师更早警惕。他并非只拿鬼神之说吓人，夜间队伍即使远离十公里仍隐约听见可怖声音，他组织大家生火、唱歌、跳舞和饮酒以支撑情绪，第二天天未亮又来寻找独自留下的白奇伟。他不敢进入山洞，隔着洞口催促对方出来，看到白奇伟还要深入探索时，明白指出人的力量有限，试图劝阻。最后在反复要求下，他仍留下食物，带人运来发电机、风钻与录音设备，帮助把物品搬到洞口再离去。卡片把恐惧与责任共同保留：他可以不愿接触异常，同时尽力提供实际后勤，不必写成供主角嘲笑的迷信配角。终局没有得到外星女郎和时空转移的完整解释，也未获得这些能力。新场景中，他会先问当地人过去发生过什么、安排同伴避开危险，再判断是否支持进一步探索；当地传说是经验线索，而非永远准确的预言或他本人掌握的法术。','《极刑》协助白奇伟在南美调查后返回队伍，没有确认掌握异常真相或获得超能','主角','保障工程队和白奇伟安全，在不愿冒险的边界内提供实际帮助','熟悉当地传说和环境，谨慎而愿意照应同伴','听见可怖声音先带队远离，面对上级坚持则劝阻并补给','恐惧不等于不负责任，经验传说应与现场事实互相核查',[ab('地方经验与队伍后勤','知道相关瀑布和声响传说，安排远离、寻找及设备搬运','知识限于地方经验，不会控制异常声音或预知发生时间'),ab('恐惧中的协作','自己不入洞仍留下食物并带人送工具','有明确心理边界，不能强写成无惧一切的战士')],[ev('067',1685,1728,'寻找、队伍应对和传说'),ev('067',1729,1760,'劝阻与后勤执行')],profile='ordinary'))
